INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bartstc/vite-ts-react-template/commit-work', 'community', 'bartstc', 'vite-ts-react-template', 'bartstc/vite-ts-react-template', 'commit-work', 0, 0, 41, '2026-02-28T12:47:07.712Z', '2026-02-28T13:12:29.478Z', '369786c13587086f6d052256a9fd4a1cdcb4173952b5bc9ce15afce9f0aeb00a', '{"id":"bartstc/vite-ts-react-template/commit-work","name":"commit-work","description":{"zh":"commit-work 是一个单页应用开发的基本开发环境，包含关键工具和设置，用于提高开发体验","ja":"commit-work はシングルページアプリケーション開発のための基本的な開発環境です。重要なツールや設定を含み、開発体験を向上させます","ko":"commit-work는 싱글페이지 애플리케이션 개발을 위한 기본 개발 환경입니다. 주요 도구와 설정을 포함하여 개발 경험을 향상시킵니다","es":"Commit-work es una configuración de desarrollo básica para aplicaciones de una sola página, con herramientas y ajustes para una experiencia de desarrollo sin problemas","fr":"Commit-work est une configuration de développement de base pour les applications à page unique, avec des outils et des paramètres pour une expérience de développement sans interruption","de":"Commit-work ist eine grundlegende Entwicklungskonfiguration für Single-Page-Anwendungen, mit Tools und Einstellungen für eine reibungslose Entwicklungserfahrung","pt":"O Commit Work fornece uma configuração de desenvolvimento básica para SPA, com ferramentas e configurações para uma experiência de desenvolvimento sem interrupções.","ru":"Commit Work предоставляет базовую настройку разработки для SPA, с инструментами и настройками для бесперебойной разработки.","ar":"ي 提供 Commit Work إعداد تطوير أساسي للتطبيقات صفحة واحدة، مع أدوات وإعدادات لتجربة تطوير بدون انقطاع.","en":"This project provides a basic dev setup intended for Single Page Application (SPA) development. It contains key tools, settings for seamless DX, and an demo app presenting good practices and used tooling in action."},"seo":{"title":{"zh":"AI智能工具：commit-work 单页应用开发","ja":"AIエージェント：commit-work シングルページアプリケーション開発","ko":"AI 에이전트: commit-work 싱글페이지 애플리케이션 개발","es":"Herramientas de IA: Configuración de commit-work para SPA","fr":"Agents IA: Configuration de commit-work pour les SPA","de":"KI-Tools: Commit-work-Konfiguration für Single-Page-Anwen...","pt":"Ferramentas de IA: Commit Work para Desenvolvedores","ru":"ИИ Агенты: Commit Work для Разработчиков","ar":"أدوات الذكاء الاصطناعي: Commit Work لل مطورين","en":"commit-work"},"description":{"zh":"commit-work 是一个单页应用开发的基本开发环境，包含关键工具和设置，用于提高开发体验","ja":"commit-work はシングルページアプリケーション開発のための基本的な開発環境です。重要なツールや設定を含み、開発体験を向上させます","ko":"commit-work는 싱글페이지 애플리케이션 개발을 위한 기본 개발 환경입니다. 주요 도구와 설정을 포함하여 개발 경험을 향상시킵니다","es":"Commit-work es una configuración de desarrollo básica para aplicaciones de una sola página, con herramientas y ajustes para una experiencia de desarrollo sin...","fr":"Commit-work est une configuration de développement de base pour les applications à page unique, avec des outils et des paramètres pour une expérience de déve...","de":"Commit-work ist eine grundlegende Entwicklungskonfiguration für Single-Page-Anwendungen, mit Tools und Einstellungen für eine reibungslose Entwicklungserfahrung","pt":"O Commit Work fornece uma configuração de desenvolvimento básica para SPA, com ferramentas e configurações para uma experiência de desenvolvimento sem interr...","ru":"Commit Work предоставляет базовую настройку разработки для SPA, с инструментами и настройками для бесперебойной разработки.","ar":"ي 提供 Commit Work إعداد تطوير أساسي للتطبيقات صفحة واحدة، مع أدوات وإعدادات لتجربة تطوير بدون انقطاع.","en":"This project provides a basic dev setup intended for Single Page Application (SPA) development. It contains key tools, settings for seamless DX, and an demo ..."},"definition":{"en":"This project provides a basic dev setup intended for Single Page Application (SPA) development. It contains key tools, settings for seamless DX, and an demo app presenting good practices and used tooling in action."},"features":{"zh":["基本的开发环境",