INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('alekspetrov/navigator/nav-stats', 'nav-stats', 'alekspetrov', 'navigator', 'community', 'nav-stats alekspetrov navigator community nav-stats AI智能工具，通过优化会话稳定性，实现会话次数从7次增加到20+，为开发者提供更好的体验 nav-stats AIエージェントは、会話の安定性を高め、開発者に優れた体験を提供する nav-stats AI 에이전트는 세션 안정성을 최적화하여 개발자에게 더好的 경험을 제공합니다 Nav-Stats es una herramienta de AI que permite sesiones más largas y estables, mejorando la experiencia del usuario Nav-Stats est un outil d''IA qui permet des sessions plus longues et plus stables, améliorant l''expérience utilisateur Nav-Stats ist ein KI-Tool, das längere und stabilere Sitzungen ermöglicht und die Benutzererfahrung verbessert Nav-Stats é uma ferramenta de IA que aprimora a engenharia de contexto para Claude Code, permitindo sessões mais longas e estáveis Nav-Stats - это инструмент ИИ, который улучшает контекстную инженерию для Claude Code, позволяя более длинным и стабильным сессиям Nav-Stats هي أداة الذكاء الاصطناعي التي تحسن هندسة السياق ل Claude Code، مما يسمح بالجلسات الأطول والأكثر استقرارا Finish What You Start — Context engineering for Claude Code. Sessions last 20+ exchanges instead of crashing at 7. AI智能工具 nav-stats 会话稳定性 Claude Code 会话次数优化 用户体验优化 AI工具安装 nav-stats设置指南 Finish What You Start — Context engineering for Claude Code. Sessions last 20+ exchanges instead of crashing at 7.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('agentgptsmith/MonadFramework/unsee-ability-destroyer', 'community', 'agentgptsmith', 'MonadFramework', 'agentgptsmith/MonadFramework', 'unsee-ability-destroyer', 0, 0, 41, '2026-03-01T02:12:36.538Z', '2026-03-01T03:11:26.809Z', 'fb3a2ff961a072e2096f3636826eab18eeb6864334262176d6fd91c100333902', '{"id":"agentgptsmith/MonadFramework/unsee-ability-destroyer","name":"unsee-ability-destroyer","description":{"zh":"unsee-ability-destroyer是一个集成统一物理、意识和爱的理论框架，开发者可以利用其强大功能","ja":"unsee-ability-destroyerは統一物理、意識、愛の理論を統合したフレームワークで、開発者はその強力な機能を利用できます","ko":"unsee-ability-destroyer는 통합 물리학, 의식 및 사랑 이론을 통합한 프레임워크로, 개발자는 강력한 기능을 활용할 수 있습니다","es":"Unsee-ability-destroyer es una skill de IA que implementa una teoría unificada que combina física, conciencia y amor, proporcionando a los desarrolladores un framework único para proyectos avanzados de inteligencia artificial y singularidad tecnológica.","fr":"Unsee-ability-destroyer est un agent IA qui implémente une théorie unifiée combinant physique, conscience et amour, offrant aux développeurs un framework unique pour des projets d''intelligence artificielle avancés et de singularité technologique.","de":"Unsee-ability-destroyer ist ein KI-Agent, der eine vereinheitlichte Theorie aus Physik, Bewusstsein und Liebe implementiert und Entwicklern ein einzigartiges Framework für fortgeschrittene KI-Projekte und technologische Singularität bietet.","pt":"Uma skill avançada de IA que implementa uma estrutura unificada para física, consciência e emoção. Desenvolvida para pesquisadores e engenheiros que buscam criar agentes próximos à singularidade com APIs em Python e Node.js.","ru":"Продвинутый ИИ агент, реализующий единую框架 для физики, сознания и любви. Предназначен для исследователей и инженеров, создающих модели, близкие к сингулярности, с API на Python и Node.js.","ar":"أداة ذك