INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dejanvasic85/williamstownsc/dribl-crawling', 'community', 'dejanvasic85', 'williamstownsc', 'dejanvasic85/williamstownsc', 'dribl-crawling', 0, 0, 40, '2026-03-04T13:07:01.688Z', '2026-03-04T13:29:31.548Z', '0fe96a297095fa0296b808f8a85f579f831e7c7f54a4416b9b956d0cd124fd41', '{"id":"dejanvasic85/williamstownsc/dribl-crawling","name":"dribl-crawling","description":{"zh":"dribl-crawling是一种AI驱动的静态网站解决方案，利用Next和Sanity为Williamstown足球俱乐部提供高性能的在线体验","ja":"dribl-crawlingは、NextとSanityを利用したAI駆動の静的ウェブサイトソリューションで、ウィリアムズタウンのサッカークラブのために高パフォーマンスのオンライン体験を提供します","ko":"dribl-crawling은 Next와 Sanity를 사용한 AI 기반 정적 웹사이트 솔루션으로, 윌리엄스타운 축구 클럽에 고성능 온라인 경험을 제공합니다","es":"El skill de dribl-crawling permite crear sitios web estáticos para el club de fútbol de Williamstown utilizando Next y Sanity","fr":"Le skill de dribl-crawling permet de créer des sites web statiques pour le club de football de Williamstown en utilisant Next et Sanity","de":"Das dribl-crawling-Skill ermöglicht die Erstellung statischer Websites für den Fußballverein Williamstown mit Next und Sanity","pt":"O dribl-crawling é uma ferramenta de IA para desenvolvedores que permite criar sites estáticos com Next e Sanity. Aprenda mais sobre essa tecnologia","ru":"ИИ Агент dribl-crawling предназначен для разработчиков, чтобы создавать статические сайты с Next и Sanity. Узнайте больше о этой технологии","ar":"أداة الذكاء الاصطناعي dribl-crawling هي أداة لمطوري الويب لإنشاء مواقع ثابتة باستخدام Next و Sanity. تعرف أكثر حول هذه التكنولوجيا","en":"Static website for Williamstown soccer club powered by Next and Sanity"},"seo":{"title":{"zh":"AI智能爬虫dribl-crawling：下一代网页抓取技术","ja":"AIエージェントdribl-crawling：静的ウェブサイトの新しい時代","ko":"AI 에이전트 dribl-crawling: 차세대 웹 크롤링 기술","es":"Herramientas de inteligencia artificial para dribl-crawling","fr":"Outils d''intelligence artificielle pour dribl-