INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('TobiasWooldridge/WaveCap-SDR/frequency-lookup', 'frequency-lookup', 'TobiasWooldridge', 'WaveCap-SDR', 'community', 'frequency-lookup TobiasWooldridge WaveCap-SDR community frequency-lookup 是 WaveCap 的 SDR 子模块，用于实现高效的频率查找 frequency-lookup は WaveCap の SDR サブモジュールであり、高効率の周波数検索を実現 frequency-lookup는 WaveCap의 SDR 서브모듈로, 효율적인 주파수 조회를 구현 Frequency-lookup es un submódulo de SDR para WaveCap que ofrece funcionalidades avanzadas para desarrolladores Frequency-lookup est un sous-module SDR pour WaveCap qui propose des fonctionnalités avancées pour les développeurs Frequency-lookup ist ein SDR-Submodul für WaveCap, das erweiterte Funktionalitäten für Entwickler bietet O frequency-lookup é um sub-módulo do SDR para WaveCap, projetado para ajudar nos processos de análise de frequência frequency-lookup - это подмодуль SDR для WaveCap, предназначенный для помощи в процессах анализа частоты frequency-lookup هو مكون فرعي ل SDR ل WaveCap، مصمم للمساعدة في عمليات تحليل التردد SDR sub-module for WaveCap 如何使用 frequency-lookup 什么是 SDR frequency-lookup 安装 WaveCap 替代品 frequency-lookup 与其他工具的比较 如何配置 frequency-lookup frequency-lookup 文档 AI智能代理工具 SDR sub-module for WaveCap');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hnabyz-bot/fpga-work/moai-foundation-core', 'community', 'hnabyz-bot', 'fpga-work', 'hnabyz-bot/fpga-work', 'moai-foundation-core', 0, 0, 40, '2026-03-04T13:07:01.692Z', '2026-03-04T13:34:54.787Z', 'ba557f6796bb1005494c38e99568e3b8d58ac73724b4bd67b0a18238d018d0ff', '{"id":"hnabyz-bot/fpga-work/moai-foundation-core","name":"moai-foundation-core","description":{"zh":"moai-foundation-core是一个FPGA开发项目，使用AI智能代理来简化开发流程","ja":"moai-foundation-coreはFPGA開発プロジェクトであり、AIエージェントを使用して開発を効率化","ko":"moai-foundation-core는 FPGA 개발 프로젝트로 AI 에이전트를 사용하여 개발 프로세스를 간소화","es":"moai-foundation-core es un proyecto de desarrollo de FPGA que aprovecha tecnologías de vanguardia para ofrecer soluciones innovadoras","fr":"moai-foundation-core est un projet de développement FPGA qui exploite les technologies de pointe pour offrir des solutions innovantes","de":"moai-foundation-core ist ein FPGA-Entwicklungsprojekt, das SpitzenTechnologien nutzt, um innovative Lösungen anzubieten","pt":"O moai-foundation-core é uma ferramenta de IA para desenvolvimento de projetos FPGA, permitindo a criação de soluções personalizadas.","ru":"Moai-foundation-core - это инструмент ИИ для разработки проектов FPGA, позволяющий создавать индивидуальные решения.","ar":"moai-foundation-core هي أداة ذكاء اصطناعي لتنمية مشاريع FPGA، مما يسمح بإنشاء حلول مخصصة.","en":"fpga 개발 프로젝트"},"seo":{"title":{"zh":"AI智能代理_moai-foundation-core FPGA开发","ja":"AIエージェント_moai-foundation-core FPGA開発","ko":"AI 에이전트_moai-foundation-core FPGA 개발 프로젝트","es":"Herramientas de AI: moai-foundation-core para FPGA","fr":"Outils d''IA: moai-foundation-core pour FPGA","de":"KI-Tools: moai-foundation-core für FPGA","pt":"Ferramentas de IA: moai-foundation-core para FPGA","ru":"ИИ Агенты: moai-foundation-core для FPGA","ar":"أدوات الذكاء الاصطناعي: moai-foundation-core ل FPGA","en":"moai-foundation-