INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mich3333/mich3333/subagents-discipline', 'subagents-discipline', 'mich3333', 'mich3333', 'community', 'subagents-discipline mich3333 mich3333 community subagents-discipline配置文件用于管理GitHub配置，优化开发者体验 subagents-discipline構成ファイルは、GitHubの設定を管理して開発者の体験を最適化する subagents-discipline 설정 파일은 GitHub 설정을 관리하여 개발자 경험을 최적화합니다 Subagents-discipline es una herramienta de AI que proporciona archivos de configuración para perfiles de GitHub, facilitando la gestión de proyectos Subagents-discipline est un outil d''IA qui fournit des fichiers de configuration pour les profils GitHub, facilitant la gestion des projets Subagents-discipline ist ein KI-Tool, das Konfigurationsdateien für GitHub-Profile bereitstellt, um die Projektverwaltung zu erleichtern Configuração de subagentes para perfil GitHub utilizando ferramentas de IA de código aberto Настройка субагентов для профиля GitHub с помощью инструментов ИИ с открытым исходным кодом تكوين الإعدادات الفرعية لملف تعريف GitHub باستخدام أدوات الذكاء الاصطناعي مفتوحة المصدر Config files for my GitHub profile. AI智能代理 subagents-discipline GitHub配置 开发者体验 配置文件管理 如何使用subagents-discipline subagents-discipline教程 GitHub设置优化 Config files for my GitHub profile.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tung68nt/tulie_lab/knowns.task.brainstorm', 'community', 'tung68nt', 'tulie_lab', 'tung68nt/tulie_lab', 'knowns.task.brainstorm', 0, 0, 40, '2026-03-04T13:07:01.720Z', '2026-03-04T13:51:32.841Z', '35ba22358662fbcbbe0c6720d3bc8313872f21c112dfb8d0be79ec1385e4541a', '{"id":"tung68nt/tulie_lab/knowns.task.brainstorm","name":"knowns.task.brainstorm","description":{"zh":"knowns.task.brainstorm是基于Next.js + Express + Prisma的LMS平台，用于开发和部署AI应用","ja":"knowns.task.brainstormは、Next.js + Express + Prismaで構成されたLMSプラットフォームで、AIアプリケーションの開発と展開を支援","ko":"knowns.task.brainstorm는 Next.js + Express + Prisma로 개발된 LMS 플랫폼으로, AI 애플리케이션의 개발과 배포를 지원","es":"knowns.task.brainstorm es una herramienta de AI para LMS que utiliza Next.js, Express y Prisma para mejorar la experiencia de aprendizaje","fr":"knowns.task.brainstorm est un outil d''IA pour les plateformes LMS qui utilise Next.js, Express et Prisma pour améliorer l''expérience d''apprentissage","de":"knowns.task.brainstorm ist ein KI-Tool für LMS-Plattformen, das Next.js, Express und Prisma verwendet, um die Lernerfahrung zu verbessern","pt":"O knowns.task.brainstorm é uma ferramenta de IA para desenvolvedores que visa ajudar no desenvolvimento de plataformas de LMS com Next.js, Express e Prisma.","ru":"ИИ Агент knowns.task.brainstorm - это инструмент для разработчиков, предназначенный для помощи в разработке платформ LMS с использованием Next.js, Express и Prisma.","ar":"knowns.task.brainstorm هو أداة ذكاء اصطناعي لمطوري التطبيقات التي تهدف إلى مساعدة في تطوير منصات LMS باستخدام Next.js و Express و Prisma.","en":"LMS Platform - The Tulie Lab (Next.js + Express + Prisma)"},"seo":{"title":{"zh":"AI工具 - knowns.task.brainstorm","ja":"AIエージェント - knowns.task.brainstorm","ko":"AI 에이전트 - knowns.task.brainstorm","es":"Herramientas de AI: knowns.task.brainstorm para LMS","fr":"Outils d''I