INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('regenrek/npm-trustme/release-npm-trustme', 'release-npm-trustme', 'regenrek', 'npm-trustme', 'community', 'release-npm-trustme regenrek npm-trustme community release-npm-trustme 是一个自动化 npm Trusted Publisher 设置的 AI 工具，帮助开发者提高效率 release-npm-trustme は npm Trusted Publisher の設定を自動化する AI エージェントです release-npm-trustme는 npm 트러스트드 퍼블리셔 설정을 자동화하는 AI 에이전트입니다 release-npm-trustme es una herramienta de AI que automatiza la configuración de Trusted Publisher en npm para mejorar la seguridad y la eficiencia release-npm-trustme est un outil d''IA qui automatise la configuration de Trusted Publisher dans npm pour améliorer la sécurité et l''efficacité release-npm-trustme ist ein KI-Tool, das die Konfiguration von Trusted Publisher in npm automatisiert, um die Sicherheit und Effizienz zu verbessern O release-npm-trustme é uma ferramenta de automação para configuração do npm Trusted Publisher, garantindo a segurança e a eficiência do seu projeto Release-npm-trustme - это инструмент для автоматизации настройки npm Trusted Publisher, обеспечивающий безопасность и эффективность вашего проекта release-npm-trustme هو أداة تلقيم لإعدادات npm Trusted Publisher، مما يضمن أمان وكفاءة مشروعك npm-trustme automates npm Trusted Publisher setup 如何使用 release-npm-trustme 什么是 npm Trusted Publisher release-npm-trustme 替代品 release-npm-trustme 安装 npm Trusted Publisher 设置指南 Node.js 开发工具 自动化 npm 设置 提高代码安全性 npm-trustme automates npm Trusted Publisher setup');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('chongdashu/phaserjs-oakwoods/playwright-testing', 'community', 'chongdashu', 'phaserjs-oakwoods', 'chongdashu/phaserjs-oakwoods', 'playwright-testing', 0, 0, 40, '2026-03-04T13:07:01.747Z', '2026-03-04T14:09:58.625Z', '44aa612c15734aba1084e3b15ad9c2dd1b7e9af00b30813875436a134fc75a4b', '{"id":"chongdashu/phaserjs-oakwoods/playwright-testing","name":"playwright-testing","description":{"zh":"Playwright 测试是一个基于 AI 的自动化测试工具，帮助开发者提高测试效率","ja":"Playwright テストは AI ベースの自動化テストツールで、開発者のテスト効率を向上させる","ko":"Playwright 테스트는 AI 기반의 자동화 테스트 도구로 개발자의 테스트 효율성을 향상시킨다","es":"Un agente de IA especializado en testing automatizado para juegos del género RPG platformer, construido con Playwright y implementado usando la metodología Vibe Code. Permite simular interacciones de usuario y validar la jugabilidad.","fr":"Un agent IA dédié aux tests automatisés pour jeux RPG platformer, construit avec Playwright et implémenté en Vibe Code. Simule les interactions joueur et valide le gameplay.","de":"Ein KI Agent für automatisierte Tests von RPG Platformer Spielen, entwickelt mit Playwright und als Vibe Code Implementierung. Simuliert Spielerinteraktionen und validiert die Gameplay-Mechanik.","pt":"Playwright-testing é uma implementação vibrante de uma plataforma de RPG, utilizando agentes de IA para testar jogos","ru":"Playwright-testing - это яркая реализация платформера RPG, использующая ИИ Агенты для тестирования игр","ar":"Playwright-testing هو تنفيذ مشفر لمنصة RPG، يستخدم وكلاء الذكاء الاصطناعي لاختبار الألعاب","en":"A vibe coded implementation of an RPG platformer"},"seo":{"title":{"zh":"AI智能工具：Playwright 测试","ja":"AIエージェント：Playwright テスト","ko":"AI 에이전트: Playwright 테스트","es":"Playwright Testing: Agente de IA para Juegos RPG Platformer","fr":"Playwright Testing: Agent IA pour Jeux RPG Platformer","de":"Playwright Testing: KI Agent für RPG Platformer Spiele","pt":"Ferramentas de Teste de Playwright - Agentes de IA","ru":"ИИ Агенты для тестирования Playwright","ar":"أدواتاختبار Playwright - وكلاء الذكاء الاصطناعي","en":"playwright-testing"},"description":{"zh":"Playwright 测试是一个基于 AI 的自动化测试工具，帮助开发者提高测试效率","ja":"Playwright テストは AI ベースの自動化テストツールで、開発者のテスト効率を向上させる","ko":"Playwright 테스트는 AI 기반의 자동화 테스트 도구로 개발자의 테스트 효율성을 향상시킨다","es":"Un agente de IA especializado en testing automatizado para juegos del género RPG platformer, construido con Playwright y implementado usando la metodología V...","fr":"Un agent IA dédié aux tests automatisés pour jeux RPG platformer, construit avec Playwright et implémenté en Vibe Code. Simule les interactions joueur et val...","de":"Ein KI Agent für automatisierte Tests von RPG Platformer Spielen, entwickelt mit Playwright und als Vibe Code Implementierung. Simuliert Spielerinteraktionen...","pt":"Playwright-testing é uma implementação vibrante de uma plataforma de RPG, utilizando agentes de IA para testar jogos","ru":"Playwright-testing - это яркая реализация платформера RPG, использующая ИИ Агенты для тестирования игр","ar":"Playwright-testing هو تنفيذ مشفر لمنصة RPG، يستخدم وكلاء الذكاء الاصطناعي لاختبار الألعاب","en":"A vibe coded implementation of an RPG platformer"},"definition":{"en":"A vibe coded implementation of an RPG platformer"},"features":{"zh":["自动化测试","提高测试效率","支持多种编程语言","易于集成","高性能"],"ja":["自動化テスト","テスト効率の向上","複数のプログラミング言語をサポート","簡単な統合","高性能"],"ko":["자동화 테스트","테스트 효율성 향상","다중 프로그래밍 언어 지원","쉬운 통합","고성능"],"es":["Automatización de pruebas E2E para RPG platformer con Playwright","Implementación en Vibe Code para desarrollo ágil","Simulación de interacciones de juego realistas","Generación de reportes de testing detallados","Integración con CI/CD pipelines","Scripting en JavaScript/TypeScript"],"fr":["Automatisation des tests E2E pour RPG platformer avec Playwright","Implémentation Vibe Code pour développement agile","Simulation d''interactions de jeu réalistes","Génération de rapports de test détaillés","Intégration avec pipelines CI/CD","Scripting en JavaScript/TypeScript"],"de":["Automatisierung von E2E Tests für RPG Platformer mit Playwright","Vibe Code Implementierung für agile Entwicklung","Simulation realistischer Spielinteraktionen","Erstellung detaillierter Testberichte","Integration in CI/CD Pipelines","Scripting in JavaScript/TypeScript"],"pt":["Implementação de código aberto","Utiliza agentes de IA para testar jogos","Suporte a plataforma de RPG","Fácil integração com outras ferramentas","Melhoria da eficiência de teste"],"ru":["Открытый исходный код","Использует ИИ Агенты для тестирования игр","Поддержка платформера RPG","Легкая интеграция с другими инструментами","Повышение эффективности тестирования"],"ar":["تنفيذ مشفر مفتوح","يستخدم وكلاء الذكاء الاصطناعي لاختبار الألعاب","دعم منصة RPG","تكامل سهل مع أدوات أخرى","تحسين كفاءة الاختبار"]},"keywords":{"zh":["如何使用 Playwright 测试","Playwright 测试教程","自动化测试工具","Playwright 测试 vs Selenium","Playwright 测试安装","Playwright 测试设置指南","AI 测试工具","Playwright 测试替代品"],"ja":["Playwright テストの使い方","Playwright テストチュートリアル","自動化テストツール","Playwright テスト vs Selenium","Playwright テストのインストール","Playwright テストの設定ガイド","AI テストツール","Playwright テストの代替"],"ko":["Playwright 테스트 사용법","Playwright 테스트 튜토리얼","자동화 테스트 도구","Playwright 테스트 vs Selenium","Playwright 테스트 설치","Playwright 테스트 설정 가이드","AI 테스트 도구","Playwright 테스트 대체"],"es":["agente de IA playwright testing","automatizar pruebas juegos RPG","playwright setup guide","vibe code implementation","playwright vs selenium","how to use playwright for games","playwright install tutorial","testing agent for platformer games"],"fr":["agent IA playwright testing","automatiser tests jeux RPG","guide installation playwright","implémentation vibe code","playwright vs selenium","comment utiliser playwright jeux","tutoriel install playwright","agent test jeux platformer"],"de":["KI Agent playwright testing","automatisierte Tests RPG Spiele","playwright setup anleitung","vibe code implementierung","playwright vs selenium","playwright für spiele verwenden","playwright install tutorial","testing agent platformer spiele"],"pt":["como usar agentes de IA para testar jogos","o que é playwright-testing","playwright-testing vs outras ferramentas","guia de instalação do playwright-testing","configuração do playwright-testing","playwright-testing para desenvolvedores","ferramentas de teste de jogos de plataforma","agentes de IA para testar jogos","playwright-testing para iniciantes"],"ru":["как использовать ИИ Агенты для тестирования игр","что такое playwright-testing","playwright-testing vs другие инструменты","руководство по установке playwright-testing","настройка playwright-testing","playwright-testing для разработчиков","инструменты для тестирования игр-платформеров","ИИ Агенты для тестирования игр","playwright-testing для начинающих"],"ar":["كيفية استخدام وكلاء الذكاء الاصطناعي لاختبار الألعاب","ما هو playwright-testing","playwright-testing مقابل أدوات أخرى","دليل تثبيت playwright-testing","إعداد playwright-testing","playwright-testing للمطورين","أدوات اختبار ألعاب المنصات","وكلاء الذكاء الاصطناعي لاختبار الألعاب","playwright-testing للمبتدئين"]}},"owner":"chongdashu","repo":"phaserjs-oakwoods","repoPath":"chongdashu/phaserjs-oakwoods","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.747Z","topics":[],"category":"community","skillMd":{"name":"playwright-testing","description":"Plan, implement, and debug frontend tests: unit/integration/E2E/visual/a11y. Use for Playwright/Cypress/Vitest/Jest/RTL, flaky test triage, CI stabilization, and canvas/WebGL games (Phaser) needing deterministic input + screenshot/state assertions.","bodyPreview":"# Frontend Testing\n\nUnlock reliable confidence fast: enable safe refactors by choosing the right test layer, making the app observable, and eliminating nondeterminism so failures are actionable.\n\n## Philosophy: Confidence Per Minute\n\nFrontend tests fail for two reasons: the product is broken, or the test is lying. Your job is to maximize signal and minimize “test is lying”.\n\n**Before writing a test, ask**:\n- What user risk am I covering (money, progression, auth, data loss, “can’t start” crashes","body":"# Frontend Testing\n\nUnlock reliable confidence fast: enable safe refactors by choosing the right test layer, making the app observable, and eliminating nondeterminism so failures are actionable.\n\n## Philosophy: Confidence Per Minute\n\nFrontend tests fail for two reasons: the product is broken, or the test is lying. Your job is to maximize signal and minimize “test is lying”.\n\n**Before writing a test, ask**:\n- What user risk am I covering (money, progression, auth, data loss, “can’t start” crashes)?\n- What’s the narrowest layer that catches this bug class (pure logic vs UI vs full browser)?\n- What nondeterminism exists (time, RNG, async loading, network, animations, fonts, GPU)?\n- What “ready” signal can I wait on besides `setTimeout`?\n- What should a failure print/screenshot so it’s diagnosable in CI?\n\n**Core principles**:\n1. **Test the contract, not the implementation**: assert stable user-meaningful outcomes and public seams.\n2. **Prefer determinism over retries**: make time/RNG/network controllable; remove flake at the source.\n3. **Observe like a debugger**: console errors, network failures, screenshots, and state dumps on failure.\n4. **One critical flow first**: a reliable smoke test beats 50 flaky tests.\n\n## Workflow Decision Tree\n\nPick the test type by the cheapest layer that provides the needed confidence:\n\n- **Unit tests** (fastest): pure functions, reducers, validators, math, pathfinding, deterministic simulation steps.\n- **Component/integration tests** (medium): UI behavior with mocked IO (React Testing Library / Vue Testing Library / Testing Library DOM).\n- **E2E tests** (slowest, highest confidence): critical user flows across routing, storage, real bundling/runtime.\n- **Visual regression** (specialized): layout/pixel regressions; for canvas/WebGL, only after locking determinism.\n- **A11y checks**: great for DOM UIs; limited value for pure canvas unless you expose accessible DOM overlays.\n\n## Quick Start (Any Project)\n\n1. **Define 1 smoke flow**: “page loads → user can start → one key action works”.\n2. **Choose runner**:\n   - Prefer **Playwright** for browser E2E + screenshots.\n   - Prefer **Testing Library** for DOM component behavior.\n   - Prefer **unit tests** for logic you can run without a browser.\n3. **Add a “ready” signal** in the app (DOM marker, window flag, or game event) and wait on that.\n4. **Fail loudly**: treat console errors and failed requests as test failures.\n5. **Stabilize**: seed RNG, freeze time, fix viewport/DPR, disable animations, and remove network variability.\n\n## Playwright Patterns (Especially Useful For Games)\n\nUse Playwright when you need “real browser” confidence:\n- Drive input via mouse/keyboard/touch; treat the canvas like the user does.\n- Add a **test seam**: expose a small, stable test API on `window` (read-only state + a few commands).\n- Prefer `waitForFunction`-style readiness over sleep; gate on “scene ready” / “assets loaded” / “first frame rendered”.\n- For screenshots: lock viewport, device scale factor, fonts, and animation timing.\n- For 9-slice / canvas UI regressions: add a dedicated UI harness scene/page and assert via targeted screenshots (see `references/phaser-canvas-testing.md`).\n\nIf using the Playwright MCP tools (browser automation inside Codex), follow the same mindset:\n- Use `browser_console_messages` and `browser_network_requests` to catch silent failures.\n- Use `browser_evaluate` to assert `window.__TEST__` state and to set up deterministic mode.\n- Use `browser_take_screenshot` for visual assertions after determinism is enforced.\n\n## Reconnaissance-Then-Action (Borrowed From Real Debugging)\n\nWhen a UI is dynamic, don’t guess selectors—recon first, then act:\n\nQuick decision guide:\n\n```\nTask → Is it static HTML (no JS runtime needed)?\n  ├─ Yes → read the HTML to find stable selectors/content, then automate\n  └─ No  → treat as dynamic: run the app, wait for readiness, then inspect rendered state\n```\n\n1. **Navigate and wait for readiness**:\n   - For many webapps: wait for a meaningful “loaded” element (preferred).\n   - `networkidle` can help for SPAs, but avoid it if the app uses websockets/polling.\n2. **Capture evidence** (what the user actually sees):\n   - screenshot (full page for DOM; targeted for canvas)\n   - console errors + failed requests\n3. **Discover selectors** from the rendered state:\n   - prefer role/text/label selectors over brittle CSS\n4. **Execute actions** using discovered selectors and re-check state.\n\nCommon pitfall:\n❌ Inspect/interact before the app is ready.\n✅ Wait on an explicit ready signal (DOM marker or `window.__TEST__.ready`), not a sleep.\n\n## Server Lifecycle Helper (Playwright E2E)\n\nWhen the dev server isn’t already running, use the bundled helper as a black box:\n- Run `python scripts/with_server.py --help` first.\n- Start one (or multiple) servers, wait for their ports, then run your test command.\n\nExample:\n```bash\npython scripts/with_server.py --server \"npm run dev\" --port 5173 -- npm test\n```\n\n## Flake Reduction Checklist\n\n- Replace sleeps with explicit readiness conditions.\n- Control time (`Date.now`, timers), RNG, and animation loops.\n- Make network deterministic (mock, record/replay, or run against a seeded local backend).\n- Eliminate “first-run” differences (asset caches, fonts) or warm them explicitly.\n- Lock environment: viewport, DPR, locale/timezone, and rendering settings.\n\n## Anti-Patterns to Avoid\n\n❌ **Testing the wrong layer**: E2E tests for pure logic.\nBetter: unit tests for logic; reserve E2E for integration contracts.\n\n❌ **Testing implementation details**: asserting DOM structure/classnames or internal engine objects.\nBetter: assert user-meaningful outputs (text, navigation, score/HP changes) or a small stable test seam.\n\n❌ **Sleep-driven tests**: `wait 2s then click`.\nBetter: wait on explicit readiness (DOM marker, event, `window` flag).\n\n❌ **Uncontrolled randomness**: RNG/time-based behaviors in assertions.\nBetter: seed RNG, freeze time, and assert stable invariants.\n\n❌ **Pixel snapshots without determinism** (especially canvas/WebGL).\nBetter: add deterministic mode first; then screenshot selectively.\n\n❌ **Snapshot explosion**: hundreds of snapshots that no one can interpret.\nBetter: keep snapshots targeted (critical screens); prefer specific assertions for behavior.\n\n❌ **Retries as a strategy**: “just bump retries in CI”.\nBetter: fix readiness and determinism; use retries only as temporary guardrails.\n\n## Variation Guidance (Prevent One-Size-Fits-All)\n\nVary the approach based on:\n- **UI type**: DOM app vs canvas/WebGL game vs hybrid.\n- **Risk**: core revenue/progression flows get E2E first; edge UI polish gets component tests.\n- **CI constraints**: headless-only, limited GPU, slow CPUs, no audio devices.\n- **Test seam availability**: if you can add a stable `window.__TEST__` API, assert state; if not, stick to black-box input/output.\n\n## Remember\n\nYou can make almost any frontend (including canvas/WebGL games) testable by adding a tiny, stable seam for readiness + state. This skill is meant to empower creative, high-signal testing rather than cargo-cult checklists. Aim for tests that are boring to maintain: deterministic, explicit about readiness, and rich in failure evidence. One reliable smoke test is the foundation; everything else compounds from there.\n\n## Bundled Resources\n\nRead these only when needed:\n- `references/playwright-mcp-cheatsheet.md`: patterns for using Playwright MCP tools for assertions, waiting, and diagnostics.\n- `references/phaser-canvas-testing.md`: deterministic mode + hooks for Phaser/canvas/WebGL games.\n- `references/flake-reduction.md`: deeper flake triage and stabilization tactics.\n\nUse these scripts as black boxes (run `--help` first; don’t read source unless you must):\n- `scripts/with_server.py`: start/wait/stop one or more dev servers around a test command.\n- `scripts/imgdiff.py`: lightweight screenshot diff helper (requires `pip install pillow`).\n"},"lastSynced":"2026-03-04T14:09:58.625Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Testing Agents needing reliable confidence in their test suites through Playwright testing","zh":"非常适合需要通过Playwright测试在测试套件中获得可靠信心的前端测试代理","ja":"Playwrightテストを通じてテストスイートで信頼できる信頼性を必要とするフロントエンドテストエージェントに最適","ko":"Playwright 테스트를 통해 테스트 스위트에서 안정적인 신뢰도를 필요로 하는 프론트엔드 테스트 에이전트에게 적합","es":"Perfecto para agentes de pruebas Frontend que necesitan confianza fiable en sus conjuntos de pruebas a través de pruebas de Playwright","fr":"Parfait pour les agents de test Frontend qui ont besoin d''une confiance fiable dans leurs jeux de tests via des tests Playwright","de":"Perfekt für Frontend-Testagenten, die eine zuverlässige Vertrauenswürdigkeit in ihren Test-Suiten durch Playwright-Tests benötigen","pt":"Perfeito para Agentes de Teste Frontend que precisam de confiança confiável em seus conjuntos de testes por meio de testes do Playwright","ru":"Идеально подходит для агентов тестирования frontend, которым требуется надежная уверенность в их наборах тестов посредством тестирования Playwright","ar":"مثالي لعمليات اختبار الواجهة الأمامية التي تحتاج إلى ثقة موثوقة في مجموعات اختبارها من خلال اختبار Playwright"},"recommendation":{"en":"Empowers agents to maximize signal and minimize false positives in their tests by eliminating nondeterminism and making the app observable, utilizing Playwright''s test layer and confidence per minute philosophy","zh":"通过消除非确定性并使应用程序可观察，利用Playwright的测试层和每分钟信心哲学，赋予代理最大化信号和最小化假阳性的能力","ja":"非決定性を排除し、アプリケーションを観測可能にすることで、Playwrightのテストレイヤーと1分間あたりの信頼性の哲学を利用して、シグナルを最大化し、偽陽性を最小限に抑える能力をエージェントに付与する","ko":"비결정성을 제거하고 애플리케이션을 관측 가능하게 함으로써, Playwright의 테스트 레이어와 1분당 신뢰도 철학을 활용하여 시그널을 최대화하고 가양성을 최소화하는 에이전트의 능력을 강화한다","es":"Habilita a los agentes a maximizar la señal y minimizar los falsos positivos en sus pruebas eliminando la no determinismo y haciendo que la aplicación sea observable, utilizando la capa de prueba de Playwright y la filosofía de confianza por minuto","fr":"Permet aux agents de maximiser le signal et de minimiser les faux positifs dans leurs tests en éliminant la non-déterminisme et en rendant l''application observable, en utilisant la couche de test de Playwright et la philosophie de confiance par minute","de":"Ermächtigt die Agenten, das Signal zu maximieren und falsche Positivergebnisse in ihren Tests zu minimieren, indem die Nichtdeterminismus eliminiert und die App beobachtbar gemacht wird, unter Verwendung von Playwrights Testlayer und der Konfidenz-pro-Minute-Philosophie","pt":"Habilita os agentes a maximizar o sinal e minimizar os falsos positivos em seus testes, eliminando a não determinismo e tornando o aplicativo observável, utilizando a camada de teste do Playwright e a filosofia de confiança por minuto","ru":"Наделяет агентов возможностью максимизировать сигнал и минимизировать ложные положительные результаты в их тестах, устраняя недетерминизм и делая приложение наблюдаемым, используя тестовый слой Playwright и философию уверенности в минуту","ar":"يمنح الوكلاء القدرة على تعظيم الإشارة وتقليل الإيجابيات الكاذبة في اختباراتهم من خلال القضاء على عدم التحديد وتجعل التطبيق مرئيًا، باستخدام طبقة اختبار Playwright وفلسفة الثقة في الدقيقة"},"useCases":{"en":["Automating frontend testing for RPG platformers","Debugging nondeterministic test failures","Optimizing test suites for confidence per minute"],"zh":["为RPG平台游戏自动化前端测试","调试非确定性测试失败","优化测试套件以获得每分钟信心"],"ja":["RPGプラットフォームゲームのフロントエンドテストの自動化","非決定性テスト失敗のデバッグ","テストスイートの信頼度を1分間あたりで最適化"],"ko":["RPG 플랫폼 게임의 프론트엔드 테스트 자동화","비결정적 테스트 실패 디버깅","테스트 스위트를 1분당 신뢰도로 최적화"],"es":["Automatizar pruebas frontend para plataformas de RPG","Depurar fallos de prueba no deterministas","Optimizar conjuntos de pruebas para confianza por minuto"],"fr":["Automatiser les tests frontend pour les plateformes de RPG","Déboguer les échecs de test non déterministes","Optimiser les jeux de tests pour la confiance par minute"],"de":["Automatisierung von Frontend-Tests für RPG-Plattformen","Fehlerbehebung bei nichtdeterministischen Testfehlern","Optimierung von Test-Suiten für Vertrauen pro Minute"],"pt":["Automatizar testes frontend para plataformas de RPG","Depurar falhas de testes não determinísticos","Otimizar conjuntos de testes para confiança por minuto"],"ru":["Автоматизация тестирования frontend для платформ RPG","Отладка неопределенных сбоев тестов","Оптимизация наборов тестов для уверенности в минуту"],"ar":["أتمتة اختبار الواجهة الأمامية لأنظمة منصات RPG","تصحيح أخطاء الاختبار غير المحددة","تحسين مجموعات الاختبار لضمان الدقيقة"]},"limitations":{"en":["Requires Playwright installation","Frontend testing only","May require additional setup for observable app"],"zh":["需要Playwright安装","仅限前端测试","可能需要额外设置以使应用程序可观察"],"ja":["Playwrightのインストールが必要","フロントエンドテストのみ","観測可能なアプリケーションにするための追加設定が必要になる場合あり"],"ko":["Playwright 설치가 필요","프론트엔드 테스트만 해당","관측 가능한 애플리케이션을 만들기 위한 추가 설정이 필요할 수 있음"],"es":["Requiere instalación de Playwright","Solo pruebas frontend","Puede requerir configuración adicional para aplicaciones observables"],"fr":["Nécessite l''installation de Playwright","Tests frontend uniquement","Peut nécessiter une configuration supplémentaire pour les applications observables"],"de":["Benötigt Playwright-Installation","Nur Frontend-Tests","Kann eine zusätzliche Einrichtung für beobachtbare Apps erfordern"],"pt":["Requer instalação do Playwright","Apenas testes frontend","Pode requerer configuração adicional para aplicativo observável"],"ru":["Требуется установка Playwright","Только тестирование frontend","Может потребовать дополнительной настройки для наблюдаемого приложения"],"ar":["يتطلب تثبيت Playwright","اختبار الواجهة الأمامية فقط","يمكن أن يتطلب إعدادًا إضافيًا للتطبيق المرئي"]},"version":3},"contentHash":"44aa612c15734aba1084e3b15ad9c2dd1b7e9af00b30813875436a134fc75a4b","qualityScore":40}');
