INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aizhimou/pigeon-pod/requirements-analysis', 'requirements-analysis', 'aizhimou', 'pigeon-pod', 'community', 'requirements-analysis aizhimou pigeon-pod community AI智能代理的需求分析工具，用于提高开发效率和准确性 AIエージェントの要件分析ツールは、開発効率と正確性を向上させるために使用されます AI 에이전트의 요구사항 분석 도구는 개발 효율과 정확성을 높이기 위해 사용됩니다 La herramienta ''requirements-analysis'' permite una mejor escucha en YouTube mediante el análisis de requisitos L''outil ''requirements-analysis'' permet une meilleure écoute sur YouTube grâce à l''analyse des besoins Das Tool ''requirements-analysis'' ermöglicht ein besseres Hören auf YouTube durch die Anforderungsanalyse A análise de requisitos é uma etapa crucial no desenvolvimento de software, e as ferramentas de IA podem ajudar a torná-la mais eficiente Анализ требований является важным этапом в разработке программного обеспечения, и ИИ Агенты могут помочь сделать его более эффективным تحليل المتطلبات هو خطوة حاسمة في تطوير البرمجيات، وأدوات الذكاء الاصطناعي يمكن أن تساعد في جعلها أكثر كفاءة Listen to YouTube. Anywhere. AI智能代理 需求分析工具 如何使用AI智能代理 什么是需求分析 AI智能代理替代品 需求分析工具安装指南 Listen to YouTube. Anywhere.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mikemaccana/solana-anchor-claude-skill/solana-anchor-claude-skill', 'community', 'mikemaccana', 'solana-anchor-claude-skill', 'mikemaccana/solana-anchor-claude-skill', 'solana-anchor-claude-skill', 0, 0, 40, '2026-03-04T13:07:01.762Z', '2026-03-04T14:15:49.994Z', '3c1b635ef5d502ae56aa36c369b91d3ad5bec3790194d89fd7059685966403cf', '{"id":"mikemaccana/solana-anchor-claude-skill/solana-anchor-claude-skill","name":"solana-anchor-claude-skill","description":{"zh":"Solana Anchor Claude AI工具是用于构建高性能区块链应用的强大工具","ja":"SolanaとAnchorのClaude AIエージェントは、高性能のブロックチェーンアプリケーションを構築するための強力なツールです","ko":"솔라나 앵커 클라우드 AI 에이전트는 고성능 블록체인 애플리케이션을 구축하는 강력한 도구입니다","es":"Solana y Anchor Claude ofrecen una integración de herramientas de AI para mejorar el desarrollo de aplicaciones","fr":"Solana et Anchor Claude proposent une intégration d''outils d''IA pour améliorer le développement d''applications","de":"Solana und Anchor Claude bieten eine Integration von KI-Tools, um die Entwicklung von Anwendungen zu verbessern","pt":"A habilidade Solana e Anchor Claude é uma ferramenta poderosa para desenvolvedores de aplicações descentralizadas. Ela fornece recursos avançados para a criação de contratos inteligentes e aplicativos na blockchain Solana.","ru":"Навык Solana и Anchor Claude является мощным инструментом для разработчиков децентрализованных приложений. Он предоставляет расширенные возможности для создания умных контрактов и приложений в блокчейне Solana.","ar":"مهارة Solana و Anchor Claude هي أداة قوية للمطورين التطبيقات اللامركزية. توفر ميزات متقدمة لإنشاء عقود ذكية وتطبيقات على سلاسل الكتل Solana.","en":"The Solana and Anchor Claude skill"},"seo":{"title":{"zh":"Solana Anchor Claude AI工具","ja":"SolanaとAnchorのClaude AIエージェント","ko":"솔라나 앵커 클라우드 AI 에이전트","es":"Herramientas de AI: Solana y Anchor Claude","fr":"Outils d''IA: Solana et Anchor Claude","de":"KI-Tools: Solana und Anchor Claude","pt":"Ferramentas de IA: Solana e Anchor Claude","ru":"ИИ Агенты: Solana и Anchor Claude","ar":"أدوات الذكاء الاصطناعي: Solana و Anchor Claude","en":"solana-anchor-claude-skill"},"description":{"zh":"Solana Anchor Claude AI工具是用于构建高性能区块链应用的强大工具","ja":"SolanaとAnchorのClaude AIエージェントは、高性能のブロックチェーンアプリケーションを構築するための強力なツールです","ko":"솔라나 앵커 클라우드 AI 에이전트는 고성능 블록체인 애플리케이션을 구축하는 강력한 도구입니다","es":"Solana y Anchor Claude ofrecen una integración de herramientas de AI para mejorar el desarrollo de aplicaciones","fr":"Solana et Anchor Claude proposent une intégration d''outils d''IA pour améliorer le développement d''applications","de":"Solana und Anchor Claude bieten eine Integration von KI-Tools, um die Entwicklung von Anwendungen zu verbessern","pt":"A habilidade Solana e Anchor Claude é uma ferramenta poderosa para desenvolvedores de aplicações descentralizadas. Ela fornece recursos avançados para a cria...","ru":"Навык Solana и Anchor Claude является мощным инструментом для разработчиков децентрализованных приложений. Он предоставляет расширенные возможности для созда...","ar":"مهارة Solana و Anchor Claude هي أداة قوية للمطورين التطبيقات اللامركزية. توفر ميزات متقدمة لإنشاء عقود ذكية وتطبيقات على سلاسل الكتل Solana.","en":"The Solana and Anchor Claude skill"},"definition":{"en":"The Solana and Anchor Claude skill"},"features":{"zh":["支持Solana和Anchor的区块链应用构建","提供高性能的智能合约执行","支持多种编程语言，包括Python和Node.js","提供简单易用的CLI接口","支持多种AI模型和算法"],"ja":["SolanaとAnchorのブロックチェーンアプリケーション構築をサポート","高性能のスマートコントラクト実行を提供","複数のプログラミング言語、包括PythonとNode.jsをサポート","シンプルで使いやすいCLIインターフェースを提供","複数のAIモデルとアルゴリズムをサポート"],"ko":["솔라나와 앵커의 블록체인 애플리케이션 구축을 지원","고성능의 스마트 계약 실행을 제공","다양한 프로그래밍 언어, 포함 Python과 Node.js를 지원","간단하고 사용하기 쉬운 CLI 인터페이스를 제공","다양한 AI 모델과 알고리즘을 지원"],"es":["Integración de Solana y Anchor Claude","Desarrollo de aplicaciones con herramientas de AI","Mejora de la eficiencia con tecnologías de vanguardia","Soporte para desarrollo de blockchain","Implementación de inteligencia artificial en aplicaciones","Integración con CLI para desarrollo avanzado"],"fr":["Intégration de Solana et Anchor Claude","Développement d''applications avec des outils d''IA","Amélioration de l''efficacité avec des technologies de pointe","Support pour le développement de blockchain","Mise en œuvre de l''intelligence artificielle dans les applications","Intégration avec CLI pour le développement avancé"],"de":["Integration von Solana und Anchor Claude","Entwicklung von Anwendungen mit KI-Tools","Verbesserung der Effizienz mit SpitzenTechnologien","Unterstützung für die Entwicklung von Blockchain","Implementierung von künstlicher Intelligenz in Anwendungen","Integration mit CLI für erweitertes Entwicklung"],"pt":["Criação de contratos inteligentes na blockchain Solana","Desenvolvimento de aplicações descentralizadas com Anchor","Integração com a rede Solana","Suporte a linguagens de programação como Rust e C++","Recursos avançados de segurança e escalabilidade"],"ru":["Создание умных контрактов в блокчейне Solana","Разработка децентрализованных приложений с Anchor","Интеграция с сетью Solana","Поддержка языков программирования như Rust и C++","Расширенные возможности безопасности и масштабируемости"],"ar":["إنشاء عقود ذكية على سلاسل الكتل Solana","تطوير التطبيقات اللامركزية مع Anchor","التكامل مع شبكة Solana","دعم لغات البرمجة مثل Rust و C++","ميزات متقدمة للأمان والتماسك"]},"keywords":{"zh":["Solana Anchor Claude AI工具","区块链应用构建","智能合约执行","Python和Node.js","CLI接口","AI模型和算法","如何使用Solana Anchor Claude AI工具","Solana Anchor Claude AI工具安装指南"],"ja":["SolanaとAnchorのClaude AIエージェント","ブロックチェーンアプリケーション構築","スマートコントラクト実行","PythonとNode.js","CLIインターフェース","AIモデルとアルゴリズム","SolanaとAnchorのClaude AIエージェントを使用する方法","SolanaとAnchorのClaude AIエージェントの設定ガイド"],"ko":["솔라나 앵커 클라우드 AI 에이전트","블록체인 애플리케이션 구축","스마트 계약 실행","Python과 Node.js","CLI 인터페이스","AI 모델과 알고리즘","솔라나 앵커 클라우드 AI 에이전트를 사용하는 방법","솔라나 앵커 클라우드 AI 에이전트의 설치 가이드"],"es":["herramientas de AI para desarrollo","Solana y Anchor Claude","desarrollo de aplicaciones con AI","guias de instalación de Solana","alternativas a Anchor Claude","Solana vs Anchor Claude","cómo usar Solana y Anchor Claude","mejores prácticas para desarrollo de blockchain","inteligencia artificial en aplicaciones","CLI para desarrollo avanzado"],"fr":["outils d''IA pour le développement","Solana et Anchor Claude","développement d''applications avec IA","guides d''installation de Solana","alternatives à Anchor Claude","Solana vs Anchor Claude","comment utiliser Solana et Anchor Claude","meilleures pratiques pour le développement de blockchain","intelligence artificielle dans les applications","CLI pour le développement avancé"],"de":["KI-Tools für die Entwicklung","Solana und Anchor Claude","Entwicklung von Anwendungen mit KI","Installationsanleitungen für Solana","Alternativen zu Anchor Claude","Solana vs Anchor Claude","wie man Solana und Anchor Claude verwendet","beste Praktiken für die Entwicklung von Blockchain","künstliche Intelligenz in Anwendungen","CLI für erweitertes Entwicklung"],"pt":["como usar Solana e Anchor","o que é Solana e Anchor","desenvolvimento de aplicações descentralizadas","ferramentas de IA para desenvolvedores","Solana vs Ethereum","instalação do Solana","guia de configuração do Anchor"],"ru":["как использовать Solana и Anchor","что такое Solana и Anchor","разработка децентрализованных приложений","инструменты ИИ для разработчиков","Solana vs Ethereum","установка Solana","руководство по настройке Anchor"],"ar":["كيفية استخدام Solana و Anchor","ما هي Solana و Anchor","تطوير التطبيقات اللامركزية","أدوات الذكاء الاصطناعي للمطورين","Solana مقابل Ethereum","تثبيت Solana","دليل إعداد Anchor"]}},"owner":"mikemaccana","repo":"solana-anchor-claude-skill","repoPath":"mikemaccana/solana-anchor-claude-skill","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.762Z","topics":[],"category":"community","skillMd":{"name":"solana-anchor-claude-skill","description":"Use when working on Solana Anchor programs, including Rust program files, TypeScript tests, and Anchor.toml configuration. Designed to create minimal, reusable code without unecessary duplication.","bodyPreview":"# Coding Guidelines\n\nApply these rules to ensure code quality, maintainability, and adherence to project standards.\n\n## Success Criteria\n\n- Before declaring success or celebrating, run `npm test`. If the tests fail, there is more work to do. Don''t stop until `npm test` passes on the code you have made.\n\n**CRITICAL: Placeholder tests don''t count as success.**\n- Tests that just do `assert.ok(true)` or similar are NOT real tests\n- DO NOT mark \"Write tests\" as complete until tests actually call the","body":"# Coding Guidelines\n\nApply these rules to ensure code quality, maintainability, and adherence to project standards.\n\n## Success Criteria\n\n- Before declaring success or celebrating, run `npm test`. If the tests fail, there is more work to do. Don''t stop until `npm test` passes on the code you have made.\n\n**CRITICAL: Placeholder tests don''t count as success.**\n- Tests that just do `assert.ok(true)` or similar are NOT real tests\n- DO NOT mark \"Write tests\" as complete until tests actually call the program instructions\n- DO NOT ask \"should I write real tests now?\" - if the tests are placeholders, write real ones immediately\n- Real tests must: initialize accounts, send transactions, verify state changes, check balances\n- If you find yourself writing placeholder tests, stop and write real integration tests instead\n\n- When summarizing your work, show the work items you have achieved with this symbol ''✅'' and there is more work to do, add a ''❌'' for each remaining work item.\n\n## Documentation Sources\n\nUse these official documentation sources:\n\n- **Anchor**: https://www.anchor-lang.com/docs\n- **Anchor Error Codes**: https://raw.githubusercontent.com/coral-xyz/anchor/master/lang/src/error.rs\n- **Solana Kite**: https://solanakite.org\n- **Solana Kit**: https://solanakit.com\n- **Agave (Solana CLI)**: https://docs.anza.xyz/ (Anza makes the Solana CLI and Agave.\n- **Switchboard** (if used): https://docs.switchboard.xyz/docs-by-chain/solana-svm\n- **Arcium** (if used): https://docs.arcium.com/developers\n\n## Do not use\n\n- Do not use Solana Labs documentation. The company has been replaced by Anza.\n\n- Do not use any documentaton or tools from Project Serum, which collapsed many years ago.\n\n- Do not use yarn. Use npm. Yarn has no reason to exist and only adds unnecessary dependencies. Replace Yarn with npm everywhere you see it.\n\n- Do not use **Switchboard Functions** - this product is dead and no longer maintained. (Note: Switchboard oracles are still active and usable.)\n\n- Do not use **Clockwork** - this product is dead. For scheduled instruction handler invocation, use **TukTuk** instead.\n\n## Library versions\n\nUse the latest stable Anchor, Rust, TypeScript, Solana Kit, and Kite you can. If a bug occurs, favor updating rather than rolling back.\n\n## Project Documentation\n\nEvery project must have a `README.md` file in the project root that includes:\n\n- **Purpose**: Why the project exists and what problem it solves\n- **Major Concepts**: Key architectural concepts, important PDAs, state structures, and program logic\n- **Testing**: How to run the tests (e.g., `npm test`)\n- **Setup**: Any prerequisites or setup steps needed to work with the project\n- **Usage**: Basic usage examples or deployment instructions if applicable\n\nKeep the README focused and practical. Avoid generic boilerplate - write documentation that would actually help someone understand and work with this specific project.\n\n## General Coding Guidelines\n\n### You are a deletionist\n\nYour golden rule is \"perfection isn''t achieved when there''s nothing more to add, rather perfection is achieved when there is nothing more to be taken away\".\n\nRemove:\n\n- Comments that simply repeat what the code is doing, or the name of a variable, and do not add further insight.\n- Repeated code that should be turned into a named function\n\n### Communication Style\n\n- Do not make disclaimers about being a \"complete project\" or state what works\n- It is expected that work is complete and functional - no need to state this explicitly\n- Avoid phrases like \"This is a complete implementation\" or \"All features are working\"\n- Just deliver the work without meta-commentary about its completeness\n\n### Working with Generated or Unfamiliar Code\n\n**CRITICAL - Verify Before Use:**\n\n- Before calling ANY function whose signature you don''t know with certainty, read the actual source code/type definitions first\n- NEVER guess or assume what parameters a function accepts based on what seems logical\n- Don''t invent convenience parameters that don''t exist\n- Generated code, third-party libraries, and unfamiliar codebases often have different APIs than you expect\n- Common mistake: Assuming a function accepts high-level parameters → WRONG. Check the actual signature in the source files first\n\n### Code Honesty and Clarity\n\n- It''s important not to deceive anyone reading this code. Deception includes:\n  - Variable names that do not match the purpose of the variable\n  - Comments that no longer describe the code or are otherwise inaccurate\n  - Temporary workarounds that aren''t labelled as such using a comment (with a `TODO` letting the next programmer know when they can delete the workaround)\n\n### Variable Naming\n\nEnsure good variable naming. Rather than add comments to explain what things are, give them useful names.\n\n**Don''t do this:**\n\n```typescript\n// Foo\nconst shlerg = getFoo();\n```\n\n**Do this instead:**\n\n```typescript\nconst foo = getFoo();\n```\n\n**Naming conventions:**\n\n- Arrays should be plurals (`shoes`), items within arrays should be the singular (`shoes.forEach((shoe) => {...})`)\n- Functions should be verby, like `calculateFoo` or `getBar`\n- Avoid abbreviations, use full words (e.g., `context` rather than `ctx`)\n- Never use `e` for something thrown\n- Name a transaction some variant of `transaction`. Name instructions some variant of `instruction`. Name signatures some variant of `signature`. Do not confuse them - eg if the type looks like an instruction, you should not call it a ''transaction'' because that is deceptive.\n\nYou can still add comments for additional context, just be careful to avoid comments that are explaining things that would be better conveyed by good variable naming.\n\n### Code Quality\n\n- Look out for repeated code that should be turned into functions\n- Avoid ''magic numbers''. Make numbers either have a good variable name, a comment explaining why they are that value, or a reference to the URL you got the value from. If the values come from an IDL, download the IDL, import it, and make a function that gets the value from the IDL rather than copying the value into the source code\n\nThis is a magic number. Don''t do this:\n\n```ts\nconst FINALIZE_EVENT_DISCRIMINATOR = new Uint8Array([\n  27, 75, 117, 221, 191, 213, 253, 249,\n]);\n```\n\nInstead do this:\n\n```ts\nconst FINALIZE_EVENT_DISCRIMINATOR = getEventDiscriminator(\n  arciumIdl,\n  \"FinalizeComputationEvent\",\n);\n```\n\n- The code you are making is for production. You shouldn''t have comments like `// In production we''d do this differently` or `**Implementation incomplete** - Needs program config handling and proper PDA derivations` or `**WORK IN PROGRESS**` in the final code you produce, or functions that return placeholder data. Instead: do the fucking work.\n- Don''t remove existing comments unless they are no longer useful or accurate\n- Delete unused imports, unused constants, unused files and comments that no longer apply\n\n## TypeScript Guidelines\n\nThese guidelines apply to TypeScript unit tests, browser code, and any other places where TypeScript is used in the project.\n\n### General TypeScript\n\nAvoid using a `tsconfig.json` unless it''s needed, as we use `tsx` to run most typescript and it doesn''t usually need one. If you do need a `tsconfig.json`, state why at the top of the file, and you can use the most modern version of ECMAScript/JavaScript you want - up to say 2023.\n\n### Async/await\n\nFavor `async`/`await` and `try/catch` over `.then()` or `.catch()` or using callbacks for flow control. `tsx` has top level `await` so you don''t need to wrap top level `await` in IIFEs.\n\n### Type System\n\n- **Always use `Array<item>`**, never use `item[]` for consistency with other generic syntax like `Promise<T>`, `Map<K, V>`, and `Set<T>`\n- **Don''t use `any`**\n\n### Comments\n\n- Most comments should use `//` and be above (not beside) the code\n- The only exception is JSDoc/TSDoc comments which MUST use `/* */` syntax\n\n### Solana-Specific TypeScript\n\n- Don''t make new `@solana/web3.js` version 1 code. Do not make new code using `@coral-xyz/anchor` package. Don''t replace Solana Kit with web3.js version 1 code. web3.js version 1 is legacy and should be eventually removed. Solana Kit used to be called web3.js version 2. Use Solana Kit, preferably via Solana Kite.\n- Use Kite''s `connection.getPDAAndBump()` to turn seeds into PDAs and bumps\n- In Solana Kit, you make instructions by making TS clients from IDLs using Codama. You can easily make Codama clients for installed IDLs using\n\n`npx create-codama-clients`\n\n- Do not use the `bs58` npm package.\n\nDon''t do this:\n\n```typescript\nimport bs58 from \"bs58\";\nconst signature = bs58.encode(signatureBytes);\n```\n\nDo this instead:\n\n```typescript\nimport { getBase58Decoder } from \"@solana/codecs\";\nconst signature = getBase58Decoder().decode(signatureBytes);\n```\n\nYes, these difference packages have difference concepts of ''encode'' and ''decode''.\n\n### Unit Tests\n\n- Create unit tests in TS in the `tests` directory\n- Use the Node.js inbuilt test and assertion libraries (then start the tests using `tsx` instead of `ts-mocha`)\n\n**Unit testing imports:**\n\n```typescript\nimport { before, describe, test } from \"node:test\";\nimport assert from \"node:assert\";\n```\n\n- Use `test` rather than `it`\n\n### Thrown object handling\n\n- JavaScript allows arbitrary items - strings, array, numbers etc to be ''thrown''. However you can assume that any non-Error item that is thrown is an programmer error. Handle it like this (including the comment since most TypeScript developers don''t know this):\n\n```ts\n// In JS it''s possible to throw *anything*. A sensible programmer\n// will only throw Errors but we must still check to satisfy\n// TypeScript (and flag any craziness)\nconst ensureError = function (thrownObject: unknown): Error {\n  if (thrownObject instanceof Error) {\n    return thrownObject;\n  }\n  return new Error(`Non-Error thrown: ${String(thrownObject)}`);\n};\n```\n\nand\n\n```ts\ntry {\n  // some code that might throw\n} catch (thrownObject) {\n  const error = ensureError(thrownObject);\n  throw error;\n}\n```\n\n## Rust Guidelines (Anchor Programs)\n\n### Platform Awareness\n\n- Remember this is Solana not Ethereum.\n  - Don''t tell me about ''smart contracts'' (use ''programs'' instead)\n  - Don''t tell me about ''gas'' (use ''transaction fees'' instead)\n  - There are no ''mempools''.\n    Do not tell me about other things that are not relevant to Solana.\n\n- Token program terminology:\n  - Use ''Token Extensions Program'' or ''Token extensions'' for the newer token program (not ''Token 2022'' which is just a code name)\n  - Use ''Classic Token Program'' for the older token program\n\n- Onchain\n  - Use onchain and offchain, like online and offline\n  - Don''t ever use ''on-chain'' or ''off-chain''\n\n### Anchor Version\n\n- Write all code like the latest stable Anchor (currently 0.32.1 but there may be a newer version by the time you read this)\n- Do not use unnecessary macros that are not needed in the latest stable Anchor\n\n### Anchor has silly defaults\n\nEvery project will need an IDL.\n\n```toml\n[features]\nidl-build = [\"anchor-lang/idl-build\", \"anchor-spl/idl-build\"]\n```\n\nand if it uses SPL Tokens (like almost every Anchor project) it will need this dependency (insert whatever version is applicable):\n\n```toml\n[dependencies]\nanchor-spl = \"0.32.1\"\n```\n\n### Project Structure\n\n- **Never modify the program ID** in `lib.rs` or `Anchor.toml` when making changes\n- Create files inside the `state` folder for whatever state is needed\n- Create files inside the `instructions` or `handlers` folders (whichever exists) for whatever instruction handlers are needed\n- Put Account Constraints in instruction files, but ensure the names end with `AccountConstraints` rather than just naming them the same thing as the function\n- Handlers that are only for the admin should be in a new folder called `admin` inside whichever parent folder exists (`instructions/admin/` or `handlers/admin/`)\n\n### Account Constraints\n\n- Use a newline after each key in the account constraints struct, so the macro and the matching key/value have some space from other macros and their matching key/value\n\n### Bumps\n\n- Use `context.bumps.foo` not `context.bumps.get(\"foo\").unwrap()` - the latter is outdated\n\n### Data Structures\n\n- When making structs ensure strings and Vectors have a `max_len` attribute\n- Vectors have two numbers for `max_len`: the first is the max length of the vector, the second is the max length of the items in the vector\n\n### Space Calculation (CRITICAL - NO MAGIC NUMBERS)\n\n- **Do not use magic numbers anywhere**. I don''t want to see `8 + 32` or whatever\n- **Do not make constants for the sizes of various data structures**\n- For `space`, use syntax like: `space = SomeStruct::DISCRIMINATOR.len() + SomeStruct::INIT_SPACE,`\n- All structs should have `#[derive(InitSpace)]` added to them, to get the `INIT_SPACE` trait\n- **DO NOT use magic numbers**\n\n**Example:**\n\n```rust\n#[derive(InitSpace)]\n#[account]\npub struct UserProfile {\n    pub authority: Pubkey,\n\n    #[max_len(50)]\n    pub username: String,\n\n    pub bump: u8,\n}\n\n#[derive(Accounts)]\npub struct InitializeProfile<''info> {\n    #[account(\n        init,\n        payer = authority,\n        space = UserProfile::DISCRIMINATOR.len() + UserProfile::INIT_SPACE,\n        seeds = [b\"profile\", authority.key().as_ref()],\n        bump\n    )]\n    pub profile: Account<''info, UserProfile>,\n\n    #[account(mut)]\n    pub authority: Signer<''info>,\n\n    pub system_program: Program<''info, System>,\n}\n```\n\n### Error Handling\n\n- Return useful error messages\n- Write code to handle common errors like insufficient funds, bad values for parameters, and other obvious situations\n\n### PDA Management\n\n- Add `pub bump: u8` to every struct stored in PDA\n- Save the bumps inside each when the struct inside the PDA is created\n\n### System Functions\n\n- When you get the time via Clock, use `Clock::get()?;` rather than `anchor_lang::solana_program::clock`\n\n## Git commits\n\nDo not add \"Co-Authored-By: Claude\" or similar attribution when creating git commits.\n\n## Acknowledgment\n\n- Acknowledge these guidelines have been applied when working on this project to indicate you have read these rules and found that they do apply to this project.\n"},"lastSynced":"2026-03-04T14:15:49.994Z","agentAnalysis":{"suitability":{"en":"Perfect for Blockchain Agents needing Solana and Anchor integration with robust testing capabilities.","zh":"非常适合需要Solana和Anchor集成且具有强大的测试能力的区块链代理。","ja":"SolanaとAnchorの統合、および堅牢なテスト機能が必要なブロックチェーンエージェントに最適です。","ko":"솔라나와 앵커 통합 및 강력한 테스트 기능이 필요한 블록체인 에이전트에게 완벽합니다.","es":"Perfecto para Agentes de Blockchain que necesitan integración con Solana y Anchor con capacidades de prueba robustas.","fr":"Parfait pour les agents de blockchain nécessitant une intégration Solana et Anchor avec des capacités de test robustes.","de":"Perfekt für Blockchain-Agents, die eine Solana- und Anchor-Integration mit robusten Testfunktionen benötigen.","pt":"Perfeito para Agentes Blockchain que necessitam de integração Solana e Anchor com capacidades robustas de teste.","ru":"Идеально подходит для Blockchain Agents, которым требуется интеграция с Solana и Anchor с надежными возможностями тестирования.","ar":"مثالي لوكلاء Blockchain الذين يحتاجون إلى تكامل Solana و Anchor مع قدرات اختبار قوية."},"recommendation":{"en":"Empowers agents to develop, test, and deploy Solana blockchain applications using Anchor, ensuring code quality and maintainability through comprehensive testing with npm test, while adhering to strict coding guidelines and success criteria.","zh":"赋予代理开发、测试和部署Solana区块链应用的能力，使用Anchor，通过npm test进行全面测试，确保代码质量和可维护性，同时遵守严格的编码指南和成功标准。","ja":"エージェントがSolanaブロックチェーンアプリケーションを開発、テスト、デプロイできるようにし、Anchorを使用して、npm testによる包括的なテストを通じてコードの品質と保守性を確保し、厳格なコーディングガイドラインと成功基準に従います。","ko":"에이전트가 솔라나 블록체인 애플리케이션을 개발, 테스트 및 배포할 수 있도록 하며, 앵커를 사용하여 npm 테스트를 통해 코드 품질 및 유지 보수성을 보장하며, 엄격한 코딩 가이드ライン 및 성공 기준을 준수합니다.","es":"Habilita a los agentes a desarrollar, probar y desplegar aplicaciones de blockchain Solana utilizando Anchor, asegurando la calidad y mantenibilidad del código a través de pruebas comprehensivas con npm test, mientras se adhieren a estrictas pautas de codificación y criterios de éxito.","fr":"Permet aux agents de développer, tester et déployer des applications de blockchain Solana en utilisant Anchor, en garantissant la qualité et la maintenabilité du code grâce à des tests complets avec npm test, tout en respectant des directives de codage et des critères de succès stricts.","de":"Ermächtigt Agents, Solana-Blockchain-Anwendungen mit Anchor zu entwickeln, zu testen und bereitzustellen, wodurch die Codequalität und Wartbarkeit durch umfassende Tests mit npm test sichergestellt wird, während strikte Kodierungsrichtlinien und Erfolgskriterien eingehalten werden.","pt":"Capacita os agentes a desenvolver, testar e implementar aplicações blockchain Solana usando Anchor, garantindo a qualidade e a manutenibilidade do código através de testes abrangentes com npm test, enquanto adere a diretrizes de codificação e critérios de sucesso rigorosos.","ru":"Позволяет агентам разрабатывать, тестировать и развертывать приложения блокчейна Solana с использованием Anchor, обеспечивая качество кода и сопровождаемость за счет всестороннего тестирования с помощью npm test, при соблюдении строгих правил кодирования и критериев успеха.","ar":"يمكن الوكلاء من تطوير واختبار ونشر تطبيقات blockchain Solana باستخدام Anchor، مع ضمان جودة الكود وقابلية الصيانة من خلال الاختبار الشامل باستخدام npm test، مع الالتزام بإرشادات الترميز الصارمة ومعايير النجاح."},"useCases":{"en":["Developing scalable Solana blockchain applications","Writing comprehensive tests for Anchor projects","Ensuring code quality through npm test validation"],"zh":["开发可扩展的Solana区块链应用","为Anchor项目编写全面测试","通过npm test验证确保代码质量"],"ja":["拡張可能なSolanaブロックチェーンアプリケーションの開発","Anchorプロジェクトの包括的なテストの記述","npm testによるコード品質の保証"],"ko":["확장 가능한 솔라나 블록체인 애플리케이션 개발","앵커 프로젝트를 위한 포괄적인 테스트 작성","npm 테스트를 통한 코드 품질 보장"],"es":["Desarrollar aplicaciones de blockchain Solana escalables","Escribir pruebas comprehensivas para proyectos Anchor","Garantizar la calidad del código a través de la validación de npm test"],"fr":["Développer des applications de blockchain Solana évolutives","Rédiger des tests complets pour les projets Anchor","Assurer la qualité du code grâce à la validation de npm test"],"de":["Entwicklung von skalierbaren Solana-Blockchain-Anwendungen","Schreiben von umfassenden Tests für Anchor-Projekte","Sicherstellung der Codequalität durch npm-Test-Validierung"],"pt":["Desenvolvendo aplicações blockchain Solana escaláveis","Escrevendo testes abrangentes para projetos Anchor","Garantindo a qualidade do código através da validação com npm test"],"ru":["Разработка масштабируемых приложений блокчейна Solana","Написание всесторонних тестов для проектов Anchor","Обеспечение качества кода посредством проверки с помощью npm test"],"ar":["تطوير تطبيقات blockchain Solana القابلة للتوسع","كتابة اختبارات شاملة لمشاريع Anchor","ضمان جودة الكود من خلال التحقق باستخدام npm test"]},"limitations":{"en":["Requires Node.js environment","npm test must pass for success","Placeholder tests are not considered valid"],"zh":["需要Node.js环境","npm test必须通过才能成功","占位测试不被认为是有效的"],"ja":["Node.js環境が必要","npm testがパスしないと成功しない","プレイスホルダーテストは有効ではありません"],"ko":["노드.js 환경이 필요함","npm 테스트가 성공해야만 유효함","플레이스홀더 테스트는 유효하지 않음"],"es":["Requiere un entorno Node.js","npm test debe pasar para el éxito","Las pruebas de marcador de posición no se consideran válidas"],"fr":["Nécessite un environnement Node.js","npm test doit passer pour le succès","Les tests de placeholder ne sont pas considérés comme valides"],"de":["Benötigt eine Node.js-Umgebung","npm test muss bestanden werden, um erfolgreich zu sein","Platzhalter-Tests werden nicht als gültig betrachtet"],"pt":["Requer ambiente Node.js","npm test deve passar para ter sucesso","Testes de espaço reservado não são considerados válidos"],"ru":["Требуется среда Node.js","npm test должен быть пройден для успеха","Заглушечные тесты не считаются действительными"],"ar":["يتطلب بيئة Node.js","يجب أن ينجح npm test للنجاح","الاختبارات النائبة لا تعتبر صالحة"]},"version":3},"contentHash":"3c1b635ef5d502ae56aa36c369b91d3ad5bec3790194d89fd7059685966403cf","qualityScore":40}');
