INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tetherto/wdk-docs/wdk', 'wdk', 'tetherto', 'wdk-docs', 'community', 'wdk tetherto wdk-docs community WDK 是一个强大的 AI 工具，提供了官方文档和集成指南，帮助开发者快速构建应用 WDK は強力な AI エージェントで、公式ドキュメントと統合ガイドを提供し、開発者が迅速にアプリケーションを構築できるようにします WDK는 강력한 AI 에이전트로, 공식 문서 및 통합 가이드를 제공하여 개발자가 빠르게 애플리케이션을 구축할 수 있도록 합니다 El WDK es un kit de desarrollo oficial para crear aplicaciones de wallet. Encuentra más información en la documentación oficial. Le WDK est un kit de développement officiel pour créer des applications de portefeuille. Trouvez plus d''informations dans la documentation officielle. Das WDK ist ein offizielles Entwicklungskit für die Erstellung von Wallet-Anwendungen. Finden Sie weitere Informationen in der offiziellen Dokumentation. A WDK é uma ferramenta de desenvolvimento oficial para criar soluções inovadoras. Acesse a documentação em docs.wallet.tether.io WDK - официальный инструмент для разработки инновационных решений. Документация на docs.wallet.tether.io WDK هي أداة تطوير رسمية لإنشاء حلول مبتكرة. وثائق على docs.wallet.tether.io Official WDK docs found at docs.wallet.tether.io 如何使用 WDK WDK 文档 WDK 集成 Wallet 开发 AI 工具 WDK 安装 WDK 教程 WDK 示例 Official WDK docs found at docs.wallet.tether.io ');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nrwl/nx-console/monitor-ci', 'community', 'nrwl', 'nx-console', 'nrwl/nx-console', 'monitor-ci', 0, 0, 40, '2026-03-04T13:07:01.889Z', '2026-03-04T14:54:26.517Z', 'd56e131636dd255ff9db343440043b82c7bd4ab253ec202c14c12d36825c2449', '{"id":"nrwl/nx-console/monitor-ci","name":"monitor-ci","description":{"zh":"Monitor-CI 是 Nx Console 的用户界面，用于 Nx 和 Lerna","ja":"Monitor-CI は Nx と Lerna のユーザー インターフェイスである Nx Console","ko":"Monitor-CI는 Nx 및 Lerna의 사용자 인터페이스인 Nx Console입니다","es":"Nx Console es la interfaz de usuario para Nx y Lerna, permitiendo una monitorización eficiente de los flujos de trabajo CI/CD","fr":"Nx Console est l''interface utilisateur pour Nx et Lerna, permettant une surveillance efficace des flux de travail CI/CD","de":"Nx Console ist die Benutzeroberfläche für Nx und Lerna, ermöglicht eine effiziente Überwachung der CI/CD-Workflows","pt":"A Nx Console é a interface do usuário para Nx e Lerna, permitindo que você monitore seu pipeline de CI de forma eficaz.","ru":"Nx Console является интерфейсом пользователя для Nx и Lerna, позволяя вам отслеживать свой конвейер CI эффективно.","ar":"Nx Console هي واجهة المستخدم لنكسلرنا ، مما يسمح لك بمراقبة خط أنابيب سي آي الخاص بك بفعالية.","en":"Nx Console is the user interface for Nx & Lerna."},"seo":{"title":{"zh":"AIエージェント Monitor-CI：Nx Console 接口","ja":"AIエージェント Monitor-CI：Nx & Lerna の UI","ko":"AI 에이전트 Monitor-CI: Nx Console 사용법","es":"Herramientas de monitoreo CI con Nx Console","fr":"Outils de surveillance CI avec Nx Console","de":"CI-Überwachungstools mit Nx Console","pt":"Ferramentas de IA: Monitor CI com Nx Console","ru":"ИИ Агенты: Monitor CI с Nx Console","ar":"أدوات الذكاء الاصطناعي: مراقبة سي آي مع Nx Console","en":"monitor-ci"},"description":{"zh":"Monitor-CI 是 Nx Console 的用户界面，用于 Nx 和 Lerna","ja":"Monitor-CI は Nx と Lerna のユーザー インターフェイスである Nx Conso