INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bitwize-music-studio/claude-ai-music-skills/configure', 'configure', 'bitwize-music-studio', 'claude-ai-music-skills', 'community', 'configure bitwize-music-studio claude-ai-music-skills community Suno音乐生产工作流为开发者提供了AI智能代理配置、模板和工具，提高音乐创作效率 Suno音楽制作ワークフローは、開発者向けのAIエージェント設定、テンプレート、ツールを提供する Suno 음악 제작 워크플로우는 개발자를 위한 AI 에이전트 설정, 템플릿, 도구를 제공합니다 El flujo de trabajo de producción musical humano y de IA para Suno implica la configuración de habilidades, plantillas y herramientas para una colaboración eficaz Le flux de travail de production musicale humain et IA pour Suno implique la configuration de compétences, de modèles et d''outils pour une collaboration efficace Der Musikproduktions-Workflow von Mensch und KI für Suno umfasst die Konfiguration von Fähigkeiten, Vorlagen und Tools für eine effektive Zusammenarbeit Configure habilidades de IA para produção musical Suno com templates e ferramentas avançadas para melhorar sua workflow Настройка ИИ Агентов для производства музыки Suno с помощью шаблонов и инструментов для улучшения вашей работы تكوين مهارات الذكاء الاصطناعي لإنتاج الموسيقى Suno مع قوالب وأدوات متقدمة لتحسين سير عملك Human + AI music production workflow for Suno - skills, templates, and tools AI智能代理配置 Suno音乐生产工作流 音乐创作效率 AI工具 音乐制作软件 如何使用Suno Suno与其他音乐制作软件的比较 Human + AI music production workflow for Suno - skills, templates, and tools');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('svetzal/hopper/hopper-coordinator', 'community', 'svetzal', 'hopper', 'svetzal/hopper', 'hopper-coordinator', 0, 0, 40, '2026-03-04T01:33:30Z', '2026-03-04T04:03:29.636Z', '192bb1cd1533f8e2f5c813459e165638621c8880bd190480fdfc5f77e9e21237', '{"id":"svetzal/hopper/hopper-coordinator","name":"hopper-coordinator","description":{"zh":"Hopper Coordinator是一个个人工作队列CLI工具，允许用户输入自由形式的描述，并使用LLM生成标题","ja":"Hopper CoordinatorはパーソナルワークキューCLIツールで、ユーザーが自由形式の説明を入力し、LLMでタイトルを生成する","ko":"Hopper Coordinator는 개인 작업 큐 CLI 도구로 사용자가 자유 형식의 설명을 입력하고 LLM으로 제목을 생성합니다","es":"Hopper Coordinator es una cola de trabajo personal en línea de comandos que convierte descripciones libres en títulos generados por LLM","fr":"Hopper Coordinator est une file d''attente personnelle en ligne de commande qui convertit des descriptions libres en titres générés par LLM","de":"Hopper Coordinator ist eine persönliche Arbeitsqueue-CLI, die freie Beschreibungen in LLM-generierte Titel umwandelt","pt":"O Hopper Coordinator é uma ferramenta de fila de trabalho personalizada em linha de comando que permite aos desenvolvedores dumping de descrições freeform e obtenção de títulos gerados por LLM","ru":"Hopper Coordinator — персональная очередь работы CLI, которая позволяет разработчикам.dumping свободных описаний и получать названия, сгенерированные ИИ","ar":"Hopper Coordinator هو أداة قائمة عمل مخصصة سطر أوامر يسمح للمطورين بتفريغ وصفات حرة وتحصل على عناوينGenerated من LLM","en":"Personal work queue CLI — dump freeform descriptions, get LLM-generated titles"},"seo":{"title":{"zh":"AI智能工具 - Hopper Coordinator：个人工作队列CLI","ja":"AIエージェント - Hopper Coordinator：パーソナルワークキューCLI","ko":"AI 에이전트 - Hopper Coordinator：개인 작업 큐 CLI","es":"Herramientas de AI: Hopper Coordinator - Cola de trabajo ...","fr":"Outils d''IA: Hopper Coordinator - File d''attente personnelle","de":"