INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('HoangNguyen0403/agent-skills-standard/React Testing', 'React Testing', 'HoangNguyen0403', 'agent-skills-standard', 'community', 'React Testing HoangNguyen0403 agent-skills-standard community React React React Nuestras mejores prácticas para pruebas de React se centran en la creación de tests confiables y escalables que se ajusten a las necesidades de tu aplicación Nos meilleures pratiques pour les tests React se concentrent sur la création de tests fiables et évolutifs qui répondent aux besoins de votre application Unsere bewährten Methoden für React-Tests konzentrieren sich auf die Erstellung zuverlässiger und skalierbarer Tests, die den Anforderungen Ihrer Anwendung entsprechen Testes em React com enfoque em comportamento do usuário, utilizando React Testing Library e Vitest Тестирование React с фокусом на поведении пользователя, используя React Testing Library и Vitest اختبار رياكت مع التركيز على سلوك المستخدم، باستخدام مكتبة اختبار رياكت و فيتست A collection of Agent Skills Standard and Best Practice for Programming Languages, Frameworks that help our AI Agent follow best practies on frameworks and programming laguages React React React React React React React A collection of Agent Skills Standard and Best Practice for Programming Languages, Frameworks that help our AI Agent follow best practies on frameworks and programming laguages');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HoangNguyen0403/agent-skills-standard/React Tooling', 'community', 'HoangNguyen0403', 'agent-skills-standard', 'HoangNguyen0403/agent-skills-standard', 'React Tooling', 0, 0, 40, '2026-02-20T04:13:19.578Z', '2026-02-20T04:52:32.792Z', '0f952b478db30b5062a83a3be3e5952fcff21f8493fda23997ec2877e2eeeb0f', '{"id":"HoangNguyen0403/agent-skills-standard/React Tooling","name":"React Tooling","description":{"zh":"React","ja":"React","ko":"React ","es":"React Tooling es una colección de habilidades estándar para programación que ayuda a los desarrolladores a seguir las mejores prácticas en frameworks y lenguajes de programación.","fr":"React Tooling est un ensemble de compétences standard pour la programmation qui aide les développeurs à suivre les meilleures pratiques dans les frameworks et les langages de programmation.","de":"React-Tooling ist eine Sammlung von Standardfähigkeiten für die Programmierung, die Entwicklern hilft, die besten Praktiken in Frameworks und Programmiersprachen zu befolgen.","pt":"As ferramentas React ajudam a otimizar e depurar projetos, melhorando a performance e a experiência do usuário. Aprenda a usá-las aqui","ru":"Инструменты React помогают оптимизировать и отладить проекты, улучшая производительность и пользовательский опыт. Узнайте, как их использовать","ar":"أدوات ري액ت تساعد على تحسين وتصحيح مشاريع، لتحسين الأداء وتجربة المستخدم. تعرف على كيفية استخدامها هنا","en":"A collection of Agent Skills Standard and Best Practice for Programming Languages, Frameworks that help our AI Agent follow best practies on frameworks and programming laguages"},"seo":{"title":{"zh":"React Tooling","ja":"React ","ko":"React ","es":"Herramientas de React","fr":"Outils de React","de":"React-Tooling","pt":"Ferramentas React: Otimização e Depuração","ru":"Инструменты React: оптимизация и отладка","ar":"أدوات ري액ت: تحسين وتصحيح","en":"React Tooling"},"description":{"zh":"React","ja":"React","ko":"React ","es":"React Tooling es una colección de habilidades estándar para programación que ayuda a los desarrolladores a seguir las mejores prácticas en frameworks y lengu...","fr":"React Tooling est un ensemble de compétences standard pour la programmation qui aide les développeurs à suivre les meilleures pratiques dans les frameworks e...","de":"React-Tooling ist eine Sammlung von Standardfähigkeiten für die Programmierung, die Entwicklern hilft, die besten Praktiken in Frameworks und Programmierspra...","pt":"As ferramentas React ajudam a otimizar e depurar projetos, melhorando a performance e a experiência do usuário. Aprenda a usá-las aqui","ru":"Инструменты React помогают оптимизировать и отладить проекты, улучшая производительность и пользовательский опыт. Узнайте, как их использовать","ar":"أدوات ري액ت تساعد على تحسين وتصحيح مشاريع، لتحسين الأداء وتجربة المستخدم. تعرف على كيفية استخدامها هنا","en":"A collection of Agent Skills Standard and Best Practice for Programming Languages, Frameworks that help our AI Agent follow best practies on frameworks and p..."},"definition":{"en":"A collection of Agent Skills Standard and Best Practice for Programming Languages, Frameworks that help our AI Agent follow best practies on frameworks and programming laguages"},"features":{"zh":["DevTools","Debugger","Performance","Bundle","Linting","Strict Mode"],"ja":["DevTools","Debugger","Performance","Bundle","Linting","Strict Mode"],"ko":["DevTools","Debugger","Performance","Bundle","Linting","Strict Mode"],"es":["DevTools","Debugger","Análisis de rendimiento","Optimización de bundles","Linting"],"fr":["DevTools","Debugger","Analyse de performance","Optimisation de bundles","Linting"],"de":["DevTools","Debugger","Leistungsanalyse","Bundle-Optimierung","Linting"],"pt":["DevTools para análise de renderização","Debugger para hooks personalizados","Otimização de performance com why-did-you-render","Análise de bundle com source-map-explorer","Linting com eslint-plugin-react-hooks"],"ru":["DevTools для анализа рендеринга","Debugger для пользовательских хуков","Оптимизация производительности с why-did-you-render","Анализ пакета с source-map-explorer","Linting с eslint-plugin-react-hooks"],"ar":["أدوات التطوير لتحليل العرض","متصفح الأخطاء ل Hooks مخصصة","تحسين الأداء مع why-did-you-render","تحليل الحزمة مع source-map-explorer","Linting مع eslint-plugin-react-hooks"]},"keywords":{"zh":["React","React Tooling","DevTools","Debugger","Performance Optimization","Bundle Optimization","Linting","Strict Mode"],"ja":["React","React ","DevTools","Debugger","Performance","Bundle","Linting","Strict Mode"],"ko":["React","React ","DevTools","Debugger","Performance","Bundle","Linting","Strict Mode"],"es":["React","Tooling","Desarrollo web","Análisis de rendimiento","Depuración","Optimización de bundles"],"fr":["React","Tooling","Développement web","Analyse de performance","Débogage","Optimisation de bundles"],"de":["React","Tooling","Webentwicklung","Leistungsanalyse","Debugging","Bundle-Optimierung"],"pt":["React","Ferramentas React","Otimização de performance","Depuração de projetos","DevTools","Debugger","why-did-you-render","source-map-explorer","eslint-plugin-react-hooks"],"ru":["React","Инструменты React","Оптимизация производительности","Отладка проектов","DevTools","Debugger","why-did-you-render","source-map-explorer","eslint-plugin-react-hooks"],"ar":["ري액ت","أدوات ري액ت","تحسين الأداء","تصحيح مشاكل","أدوات التطوير","متصفح الأخطاء","why-did-you-render","source-map-explorer","eslint-plugin-react-hooks"]}},"owner":"HoangNguyen0403","repo":"agent-skills-standard","repoPath":"HoangNguyen0403/agent-skills-standard","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.578Z","topics":[],"category":"community","skillMd":{"name":"React Tooling","description":"Debugging, build analysis, and ecosystem tools.","bodyPreview":"# React Tooling\n\n## **Priority: P2 (OPTIONAL)**\n\nTools for analysis and debugging.\n\n## Implementation Guidelines\n\n- **DevTools**: Use \"Highlight Updates\" to spot re-renders.\n- **Debugger**: `useDebugValue` for custom hooks.\n- **Performance**: `why-did-you-render` to catch wasted renders.\n- **Bundle**: `source-map-explorer` or `bundle-visualizer`.\n- **Linting**: `eslint-plugin-react-hooks` (Errors) + `react-refresh`.\n- **Strict Mode**: Enable for double-invoke checks (effects/reducers).\n\n## Code","body":"# React Tooling\n\n## **Priority: P2 (OPTIONAL)**\n\nTools for analysis and debugging.\n\n## Implementation Guidelines\n\n- **DevTools**: Use \"Highlight Updates\" to spot re-renders.\n- **Debugger**: `useDebugValue` for custom hooks.\n- **Performance**: `why-did-you-render` to catch wasted renders.\n- **Bundle**: `source-map-explorer` or `bundle-visualizer`.\n- **Linting**: `eslint-plugin-react-hooks` (Errors) + `react-refresh`.\n- **Strict Mode**: Enable for double-invoke checks (effects/reducers).\n\n## Code\n\n```tsx\n// Debugging Hooks\nuseDebugValue(isOnline ? ''Online'' : ''Offline'');\n\n// why-did-you-render\nif (process.env.NODE_ENV === ''development'') {\n  const whyDidYouRender = require(''@welldone-software/why-did-you-render'');\n  whyDidYouRender(React, {\n    trackAllPureComponents: true,\n  });\n}\n```\n"},"lastSynced":"2026-02-20T04:52:32.792Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents focused on optimizing React applications with advanced tooling and debugging capabilities.","zh":"适用于专注于优化React应用程序的前端代理，具有高级工具和调试功能。","ja":"Reactアプリケーションの最適化に焦点を当てたフロントエンドエージェントに適しています。高度なツールとデバッグ機能を備えています。","ko":"React 애플리케이션을 최적화하는 데 중점을 둔 프론트엔드 에이전트에게 적합합니다. 고급 도구 및 디버깅 기능을 제공합니다.","es":"Ideal para agentes de frontend centrados en optimizar aplicaciones de React con herramientas avanzadas y capacidades de depuración.","fr":"Idéal pour les agents de frontend axés sur l''optimisation des applications React avec des outils avancés et des capacités de débogage.","de":"Ideal für Frontend-Agenten, die auf die Optimierung von React-Anwendungen mit erweiterten Werkzeugen und Debugging-Funktionen ausgerichtet sind.","pt":"Ideal para Agentes Frontend focados na otimização de aplicações React com ferramentas avançadas e capacidades de depuração.","ru":"Идеально подходит для агентов Frontend, ориентированных на оптимизацию приложений React с помощью продвинутых инструментов и возможностей отладки.","ar":"مثالي لعميل واجهة المستخدم المعني بتحسين تطبيقات React باستخدام أدوات متقدمة وقدرات فحص الأخطاء."},"recommendation":{"en":"Empowers agents to optimize React performance using tools like `why-did-you-render` for catching wasted renders, `source-map-explorer` for bundle analysis, and `eslint-plugin-react-hooks` for strict linting, ensuring efficient and error-free code execution.","zh":"赋予代理优化React性能的能力，使用诸如`why-did-you-render`捕获浪费渲染、`source-map-explorer`进行包分析和`eslint-plugin-react-hooks`进行严格的代码检查等工具，确保代码的高效和无错误执行。","ja":"エージェントにReactのパフォーマンスを最適化する能力を与えます。`why-did-you-render`を使用して不要な再描画をキャッチし、`source-map-explorer`を使用してバンドル分析を実行し、`eslint-plugin-react-hooks`を使用して厳格なリンティングを実行するなど、効率的でエラーのないコード実行を保証します。","ko":"에이전트에 React 성능을 최적화하는 능력을 부여합니다. `why-did-you-render`를 사용하여 쓸모없는 재描画를捕获하고, `source-map-explorer`를 사용하여 번들 분석을 수행하며, `eslint-plugin-react-hooks`를 사용하여 엄격한 린팅을 수행하여 효율적이고 오류가 없는 코드 실행을 보장합니다.","es":"Permite a los agentes optimizar el rendimiento de React utilizando herramientas como `why-did-you-render` para detectar renderizados desperdiciados, `source-map-explorer` para el análisis de paquetes y `eslint-plugin-react-hooks` para una verificación estricta, garantizando una ejecución de código eficiente y sin errores.","fr":"Permet aux agents d''optimiser les performances de React en utilisant des outils comme `why-did-you-render` pour détecter les rendus inutiles, `source-map-explorer` pour l''analyse des bundles et `eslint-plugin-react-hooks` pour une vérification stricte, garantissant une exécution de code efficace et sans erreurs.","de":"Ermächtigt Agenten, die Leistung von React zu optimieren, indem sie Tools wie `why-did-you-render` zur Erkennung von verschwendeten Renderungen, `source-map-explorer` zur Bundle-Analyse und `eslint-plugin-react-hooks` für eine strenge Überprüfung verwenden, um eine effiziente und fehlerfreie Codeausführung sicherzustellen.","pt":"Habilita os agentes a otimizar o desempenho do React usando ferramentas como `why-did-you-render` para capturar renderizações desperdiçadas, `source-map-explorer` para análise de pacotes e `eslint-plugin-react-hooks` para linting estrito, garantindo execução de código eficiente e sem erros.","ru":"Предоставляет агентам возможность оптимизировать производительность React с помощью инструментов như `why-did-you-render` для поимки бесполезных рендеров, `source-map-explorer` для анализа пакетов и `eslint-plugin-react-hooks` для строгого линтинга, гарантируя эффективную и безошибочную выполнение кода.","ar":"تمكّن الوكلاء من تحسين أداء React باستخدام أدوات مثل `why-did-you-render` للقبض على عمليات التصفح المهدرة، و `source-map-explorer` لتحليل الحزم، و `eslint-plugin-react-hooks` للتحليل المتخفيض، مما يضمن تنفيذ 코드 فعالاً وخاليًا من الأخطاء."},"useCases":{"en":["Debugging re-renders with DevTools'' Highlight Updates","Analyzing bundle sizes with `source-map-explorer` or `bundle-visualizer`","Implementing custom hooks with `useDebugValue` for enhanced debugging"],"zh":["使用DevTools的Highlight Updates调试重新渲染","使用`source-map-explorer`或`bundle-visualizer`分析包大小","使用`useDebugValue`实现自定义钩子以增强调试"],"ja":["DevToolsのHighlight Updatesを使用して再描画をデバッグする","`source-map-explorer`または`bundle-visualizer`を使用してバンドルサイズを分析する","`useDebugValue`を使用してカスタムフックを実装してデバッグを強化する"],"ko":["DevTools의 Highlight Updates를 사용하여 재描画를 디버깅합니다.","`source-map-explorer` 또는 `bundle-visualizer`를 사용하여 번들 크기 분석","`useDebugValue`를 사용하여 사용자 정의 후크를 구현하여 디버깅을 강화합니다."],"es":["Depuración de nuevas renderizaciones con DevTools'' Highlight Updates","Análisis de tamaños de paquetes con `source-map-explorer` o `bundle-visualizer`","Implementación de ganchos personalizados con `useDebugValue` para una depuración mejorada"],"fr":["Débogage des re-rendus avec DevTools'' Highlight Updates","Analyse des tailles de bundles avec `source-map-explorer` ou `bundle-visualizer`","Implémentation de crochets personnalisés avec `useDebugValue` pour un débogage amélioré"],"de":["Fehlerbehebung von Neu-Renderungen mit DevTools'' Highlight Updates","Analyse von Bundle-Größen mit `source-map-explorer` oder `bundle-visualizer`","Implementierung von benutzerdefinierten Hooks mit `useDebugValue` für eine verbesserte Fehlersuche"],"pt":["Depuração de re-renderizações com Highlight Updates do DevTools","Análise de tamanhos de pacotes com `source-map-explorer` ou `bundle-visualizer`","Implementação de ganchos personalizados com `useDebugValue` para depuração aprimorada"],"ru":["Отладка повторных рендеров с помощью Highlight Updates от DevTools","Анализ размеров пакетов с помощью `source-map-explorer` или `bundle-visualizer`","Реализация пользовательских крючков с помощью `useDebugValue` для улучшенной отладки"],"ar":["فحص إعادة التصيير باستخدام أداة DevTools'' Highlight Updates","تحليل أحجام الحزم باستخدام `source-map-explorer` أو `bundle-visualizer`","تطبيق مشابك مخصصة باستخدام `useDebugValue` من أجل فحص محسّن"]},"limitations":{"en":["Requires React framework","Limited to JavaScript ecosystem","Dependent on compatible versions of `eslint-plugin-react-hooks` and `react-refresh`"],"zh":["需要React框架","仅限于JavaScript生态系统","依赖于`eslint-plugin-react-hooks`和`react-refresh`的兼容版本"],"ja":["Reactフレームワークが必要","JavaScriptエコシステムに限定される","`eslint-plugin-react-hooks`と`react-refresh`の互換バージョンに依存する"],"ko":["React 프레임워크가 필요합니다.","JavaScript 생태계에만 국한됩니다.","`eslint-plugin-react-hooks` 및 `react-refresh`의 호환 버전에 종속됩니다."],"es":["Requiere el marco de React","Limitado al ecosistema de JavaScript","Dependiente de versiones compatibles de `eslint-plugin-react-hooks` y `react-refresh`"],"fr":["Nécessite le framework React","Limité à l''écosystème JavaScript","Dépendant de versions compatibles de `eslint-plugin-react-hooks` et `react-refresh`"],"de":["Benötigt das React-Framework","Begrenzt auf das JavaScript-Ökosystem","Abhängig von kompatiblen Versionen von `eslint-plugin-react-hooks` und `react-refresh`"],"pt":["Exige o framework React","Limitado ao ecossistema JavaScript","Dependente de versões compatíveis de `eslint-plugin-react-hooks` e `react-refresh`"],"ru":["Требует фреймворка React","Ограничен экосистемой JavaScript","Зависит от совместимых версий `eslint-plugin-react-hooks` и `react-refresh`"],"ar":["يتطلب إطار عمل React","محدود ببيئة JavaScript","يعتمد على إصدارات متوافقة من `eslint-plugin-react-hooks` و `react-refresh`"]},"version":3},"contentHash":"0f952b478db30b5062a83a3be3e5952fcff21f8493fda23997ec2877e2eeeb0f","qualityScore":40}');
